import { test as base, expect } from 'vitest'

const it = base.extend<{ account: Account }>({
  account: async ({}, use) => {
    await use(new Account(100))             // Arrange fixture
  },
})

it('reduces the balance when 30 is withdrawn', ({ account }) => {
  const ok = account.withdraw(30)           // Act
  expect(ok).toBe(true)                     // Assert
  expect(account.balance).toBe(70)
})
